// Metroidvania dashboard. Data comes from data.js (window.METROIDVANIA_DASHBOARD),
// generated by build/fusion_dashboard, so the page works from file:// without any request.
(function () {
  "use strict";

  const data = window.METROIDVANIA_DASHBOARD;
  const view = document.getElementById("view");
  const toolbar = document.getElementById("toolbar");
  const search = document.getElementById("search");
  const statusFilter = document.getElementById("status-filter");
  const REPOSITORY_URL = "https://github.com/wozt/metroidvania";

  const VERDICTS = {
    passing: ["Tests passed", "ok"],
    failing: ["Tests failed", "bad"],
    tests_not_run: ["Tests not run", "warn"],
    untested: ["No tests", "warn"],
    unregistered_tests: ["Tests not registered", "warn"],
    missing_sources: ["Sources missing", "bad"],
  };
  const AREA_VIEWS = ["mzm", "aos", "metroidvania", "story", "tools", "assets", "platform"];
  const state = { view: "overview", query: "", statuses: new Set() };

  function esc(value) {
    return String(value == null ? "" : value).replace(/[&<>"']/g, (c) => ({
      "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;",
    })[c]);
  }
  function statusInfo(id) {
    return data.statuses.find((s) => s.id === id) || { id, label: id, description: "" };
  }
  function statusBadge(id) {
    const s = statusInfo(id);
    return `<span class="badge" title="${esc(s.description)}"><span class="dot" style="background:var(--s-${esc(id)})"></span>${esc(s.label)}</span>`;
  }
  function verdictBadge(verification) {
    const [label, tone] = VERDICTS[verification.verdict] || [verification.verdict, "warn"];
    return `<span class="badge ${tone}" title="Checked automatically when the data was generated">${esc(label)}</span>`;
  }
  function percent(value) {
    return value == null ? "n/a" : `${value}%`;
  }
  function areaTitle(id) {
    const area = data.areas.find((a) => a.id === id);
    return area ? area.title : id;
  }

  function repositoryPath(path) {
    const encoded = String(path).split("/").map(encodeURIComponent).join("/");
    if (location.protocol === "file:") return `../${encoded}`;
    const branch = encodeURIComponent((data && data.git && data.git.branch) || "main");
    return `${REPOSITORY_URL}/blob/${branch}/${encoded}`;
  }
  function fileLink(path, label) {
    if (!path || path.startsWith("@")) return `<code>${esc(label || path)}</code>`;
    return `<a class="file-link" href="${esc(repositoryPath(path))}"><code>${esc(label || path)}</code></a>`;
  }

  function matches(feature) {
    if (state.statuses.size && !state.statuses.has(feature.status)) return false;
    if (!state.query) return true;
    const haystack = [feature.id, feature.title, feature.category, feature.limitations,
      feature.next_action, ...feature.local_sources, ...feature.tests,
      ...feature.native_routines].join(" ").toLowerCase();
    return state.query.split(/\s+/).every((word) => haystack.includes(word));
  }

  function stackBar(byStatus, total) {
    if (!total) return '<div class="stack"></div>';
    const parts = data.statuses.filter((s) => byStatus[s.id]).map((s) =>
      `<span style="width:${(100 * byStatus[s.id]) / total}%;background:var(--s-${s.id})" title="${esc(s.label)}: ${byStatus[s.id]}"></span>`);
    return `<div class="stack" role="img" aria-label="Status distribution">${parts.join("")}</div>`;
  }
  function legend(byStatus) {
    return `<div class="legend">${data.statuses.filter((s) => byStatus[s.id]).map((s) =>
      `<span><i style="background:var(--s-${s.id})"></i>${esc(s.label)} ${byStatus[s.id]}</span>`).join("")}</div>`;
  }
  function metric(label, value, count, total, cls) {
    return `<div class="metric"><div class="label"><span>${esc(label)}</span><span>${percent(value)} · ${count}/${total}</span></div>
      <div class="bar"><span class="${cls}" style="width:${value || 0}%"></span></div></div>`;
  }

  function evidenceBadges(evidence, verification) {
    if (!evidence) return "";
    const testsDeclared = evidence.unit_tests.length > 0;
    const testsPassed = testsDeclared && verification && verification.verdict === "passing";
    const testsFailed = testsDeclared && verification && verification.verdict === "failing";
    const badges = [
      [testsPassed ? "ok" : testsFailed ? "bad" : testsDeclared ? "declared" : "none",
       testsPassed ? "Tests passed" : testsFailed ? "Tests failed" : testsDeclared ? "Tests declared" : "No tests",
       evidence.unit_tests.join(", ") || "no automated test declared"],
      [evidence.in_game_check.length ? "ok" : "none", "In-game check",
       evidence.in_game_check.join(", ") || "no recorded manual runtime check"],
      [evidence.emulator_compared ? "ok" : "none", "Emulator comparison",
       evidence.emulator_compared ? "compared with an emulator" : "not compared with an emulator"],
      [evidence.played_through ? "ok" : "none", "Played through",
       evidence.played_through ? "played to its end" : "not played to its end"],
    ];
    return `<span class="evidence">${badges.map(([tone, label, hint]) => {
      const symbol = tone === "ok" ? "✓" : tone === "bad" ? "✗" : tone === "declared" ? "•" : "—";
      return `<span class="badge evidence-${tone}" title="${esc(hint)}">${symbol} ${esc(label)}</span>`;
    }).join("")}</span>`;
  }

  function featureCard(feature) {
    const v = feature.verification;
    const rows = [];
    const list = (items, mono) => items.map((x) => mono ? `<code>${esc(x)}</code>` : esc(x)).join(", ");
    if (feature.local_sources.length) rows.push(["Implementation", feature.local_sources.map((x) => fileLink(x)).join(", ")]);
    if (feature.tests.length) rows.push(["Tests", v.tests.map((t) =>
      `${fileLink(t.test)}${t.ctest && t.ctest.length ? ` <span class="muted">(${esc(t.ctest.join(", "))})</span>` : ""}${t.outcome ? ` — ${esc(t.outcome)}` : ""}`).join("<br>")]);
    if (feature.native_routines.length) rows.push(["Native routines", list(feature.native_routines, true)]);
    if (feature.dependencies.length) rows.push(["Depends on", list(feature.dependencies, true)]);
    rows.push(["Fidelity", esc(feature.fidelity)]);
    if (feature.limitations) rows.push(["Limitations", esc(feature.limitations)]);
    if (feature.next_action) rows.push(["Next", esc(feature.next_action)]);
    rows.push(["Declared in", fileLink(feature.source)]);
    if (v.verified_on) rows.push(["Verified", esc(v.verified_on)]);
    else if (feature.last_validated) rows.push(["Last validated (declared)", esc(feature.last_validated)]);
    return `<article class="feature">
      <div class="row"><span class="name">${esc(feature.title)}</span><code class="id">${esc(feature.id)}</code></div>
      <div class="row">${statusBadge(feature.status)} ${verdictBadge(v)}</div>
      <div class="row">${evidenceBadges(feature.evidence, v)}</div>
      ${v.warnings.map((w) => `<div class="warning">⚠ ${esc(w)}</div>`).join("")}
      <dl>${rows.map(([k, val]) => `<dt>${esc(k)}</dt><dd>${val}</dd>`).join("")}</dl>
    </article>`;
  }

  function featureGroups(features, open) {
    const groups = new Map();
    features.forEach((f) => {
      const key = `${areaTitle(f.area)} · ${f.category}`;
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key).push(f);
    });
    if (!groups.size) return '<p class="notice">No feature matches the search and filters.</p>';
    return [...groups.entries()].map(([title, items]) => {
      const counts = {};
      items.forEach((f) => { counts[f.status] = (counts[f.status] || 0) + 1; });
      return `<details class="group"${open ? " open" : ""}>
        <summary><span class="title">${esc(title)}</span><span class="muted">${items.length} feature${items.length > 1 ? "s" : ""}</span></summary>
        <div style="padding:0 14px 10px">${stackBar(counts, items.length)}${legend(counts)}</div>
        ${items.map(featureCard).join("")}
      </details>`;
    }).join("");
  }

  function indicatorCard(indicator, includeFeatures = true) {
    const cls = indicator.id === "mzm" ? "mzm" : indicator.id === "aos" ? "aos" : indicator.id === "global" ? "global" : "";
    const features = data.features.filter((f) => indicator.features.includes(f.id) && matches(f));
    return `<div class="card ${cls}">
      <header><h3>${esc(indicator.title)}</h3><span class="muted">${indicator.total} registered</span></header>
      ${metric("Functional or better", indicator.functional_or_better_percent, indicator.functional_or_better, indicator.total, "working")}
      ${metric("With passing tests", indicator.with_passing_tests_percent, indicator.with_passing_tests, indicator.total, "tested")}
      ${stackBar(indicator.by_status, indicator.total)}${legend(indicator.by_status)}
      ${includeFeatures ? `<details class="group" style="margin:10px 0 0"><summary><span class="title">Features</span><span class="muted">${features.length}</span></summary>
        ${features.map(featureCard).join("") || '<p class="feature muted">No match.</p>'}</details>` : ""}
    </div>`;
  }

  function testsIndicator() {
    const t = data.tests;
    if (!t.summary) {
      return `<div class="card"><header><h3>Automated tests</h3></header>
        <p class="muted">Tests were not run when this data was generated (use <code>--run-tests</code>).
        ${t.ctest.length} CTest tests are registered.</p></div>`;
    }
    const total = t.summary.passed + t.summary.failed + t.summary.other;
    const share = total ? Math.round((1000 * t.summary.passed) / total) / 10 : null;
    return `<div class="card"><header><h3>Automated tests</h3><span class="muted">on ${esc(t.host)}</span></header>
      <div class="big">${t.summary.passed}<span class="muted" style="font-size:1rem"> / ${total} passed</span></div>
      ${metric("Passing", share, t.summary.passed, total, "tested")}
      <p class="muted" style="margin:6px 0 0">${t.summary.failed} failed, ${t.summary.other} skipped or not run.
      ${t.ctest.length} CTest tests.</p></div>`;
  }

  function inventoryPanel() {
    const inv = data.inventory;
    if (!inv || !inv.available) return "";
    const cards = ["mzm", "aos"].map((game) => {
      const g = inv.games[game];
      const unclassified = g.by_category.unclassified || 0;
      const attached = g.routines_attached_to_features ?? g.routines_cited_by_features;
      const unassigned = g.unassigned_routines ?? (g.routines - attached);
      return `<div class="card ${game}"><header><h3>${esc(g.title)}</h3><span class="muted">native source inventory</span></header>
        <div class="big">${g.routines.toLocaleString("en")}<span class="muted" style="font-size:1rem"> routines discovered</span></div>
        <p class="muted" style="margin:8px 0 0">${(g.routines - unclassified).toLocaleString("en")} classified,
        ${unclassified.toLocaleString("en")} unclassified; ${attached.toLocaleString("en")} attached to reviewed features,
        ${unassigned.toLocaleString("en")} not yet attached; ${g.call_edges.toLocaleString("en")} call edges.
        Discovered and attached do not mean ported: implementation is tracked by the features above.</p></div>`;
    });
    return `<h2>Native source inventory</h2><div class="grid">${cards.join("")}</div>`;
  }

  /* Catalog navigation (one canonical list per game and category).
   * All counts come from the native C generator; detail rows are rendered only
   * by bestiaryView(), never duplicated across Overview and game tabs. */
  function catalogSnapshot(game) {
    const catalog = data.bestiary && data.bestiary.games && data.bestiary.games[game];
    if (!catalog || !catalog.coverage) return "";
    const sections = game === "mzm" ? [
      ["Enemy and boss actors", "monsters"], ["Items and pickups", "items"]
    ] : [
      ["Monsters", "monsters"], ["Bosses", "bosses"], ["Items", "items"],
      ["Red souls", "red_souls"], ["Blue souls", "blue_souls"],
      ["Yellow souls", "yellow_souls"], ["Ability souls", "ability_souls"]
    ];
    const categories = sections.filter(([, key]) => catalog.coverage[key]);
    return `<section class="catalog-preview catalog-${esc(game)}">
      <div class="catalog-preview-heading"><h3>${esc(catalog.title)}</h3>
      <a href="#bestiary" data-open-view="bestiary">Browse complete catalogs</a></div>
      ${coverageCards(categories.map(([label, key]) => [label, catalog.coverage[key], game]))}
    </section>`;
  }

  function overview() {
    const indicators = data.indicators.map(indicatorCard).join("");
    return `<p class="notice">${esc(data.method)}</p>
      <p class="notice evidence-note"><strong>Evidence is separate from implementation status.</strong>
      “Tests declared” only means a test is registered; “Tests passed” means it passed during this
      dashboard generation. In-game checks are recorded manual observations. Emulator comparison
      and playthrough are independent evidence.</p>
      <h2>Native catalog coverage</h2>
      <p class="muted">Auto-generated from the native C catalog and parity registries. Catalog completion is not the same as engine or game completion; details are shown once in Monsters &amp; items.</p>
      ${catalogSnapshot("mzm")}${catalogSnapshot("aos")}
      <h2>Indicators</h2><div class="grid">${indicators}${testsIndicator()}</div>
      ${inventoryPanel()}`;
  }

  function areaView(area) {
    const all = data.features.filter((f) => f.area === area);
    const indicator = data.indicators.find((i) => i.areas.length === 1 && i.areas[0] === area);
    const visible = all.filter(matches);
    return `${area === "mzm" || area === "aos" ? catalogSnapshot(area) : ""}
      <div class="grid">${indicator ? indicatorCard(indicator, false) : ""}</div>
      <h2>${esc(areaTitle(area))}</h2>${featureGroups(visible, true)}`;
  }

  function outcomeBadge(outcome) {
    if (outcome == null) return '<span class="badge warn">not run</span>';
    const tone = outcome === "passed" ? "ok" : outcome === "failed" ? "bad" : "warn";
    return `<span class="badge ${tone}">${esc(outcome)}</span>`;
  }

  function testsView() {
    const t = data.tests;
    const q = state.query;
    const ctest = t.ctest.filter((x) => !q || (x.name + " " + x.files.join(" ")).toLowerCase().includes(q));
    return `<div class="grid">${testsIndicator()}</div>
      <h2>CTest (${ctest.length})</h2>
      <div class="table-wrap"><table><thead><tr><th>Test</th><th>Sources</th><th>Result</th></tr></thead><tbody>
      ${ctest.map((x) => `<tr><td><code>${esc(x.name)}</code></td><td>${x.files.map((f) => fileLink(f)).join("<br>") || '<span class="muted">command</span>'}</td><td>${outcomeBadge(x.outcome)}</td></tr>`).join("")}
      </tbody></table></div>`;
  }

  function timelineView() {
    const q = state.query;
    const entries = data.timeline.filter((e) => !q || (e.subject + " " + e.scope).toLowerCase().includes(q));
    return `<p class="notice">Commit history shows when work landed; it is not evidence that a feature works.</p>
      <ul class="timeline">${entries.map((e) => `<li class="scope-${esc(e.scope)}">
        <div class="date">${esc(e.date)} · <a href="${esc(`${REPOSITORY_URL}/commit/${encodeURIComponent(e.commit)}`)}"><code>${esc(e.commit)}</code></a> · ${esc(e.scope)}</div>
        <div>${esc(e.subject)}</div></li>`).join("")}</ul>`;
  }

  function attentionView() {
    const flagged = data.features.filter((f) => matches(f) && (
      ["blocked", "unknown", "not_started", "in_progress", "partial"].includes(f.status) ||
      f.verification.warnings.length || ["failing", "missing_sources"].includes(f.verification.verdict)));
    const order = ["blocked", "unknown", "not_started", "in_progress", "partial", "functional", "faithful", "validated"];
    flagged.sort((a, b) => order.indexOf(a.status) - order.indexOf(b.status));
    const warnings = data.features.filter((f) => f.verification.warnings.length).length;
    return `<p class="notice">${flagged.length} features are blocked, unknown, unfinished or carry a verification warning
      (${warnings} with warnings).</p>${featureGroups(flagged, false)}`;
  }

  function coverageCards(groups) {
    return `<div class="catalog-summary">${groups.map(([name, coverage, tone]) =>
      `<div class="catalog-count ${esc(tone || "")}"><strong>${coverage.functional_or_better_percent}%</strong><span>${esc(name)} · ${coverage.functional_or_better}/${coverage.total} functional+</span></div>`
    ).join("")}</div>`;
  }

  function bestiaryTable(rows, kind, coverage, aspects) {
    const q = state.query;
    const visible = rows.filter((row) =>
      (!state.statuses.size || state.statuses.has(row.status)) &&
      (!q || (row.name + " " + (row.note || "") + " " + (row.feature || "") + " " +
        (row.aspects ? row.aspects.notes + " " + row.aspects.soul_ref : "")).toLowerCase().includes(q)));
    const aspectHeaders = aspects ? `${aspectNames.map((name) => `<th>${esc(name)}</th>`).join("")}<th>Soul reference</th>` : "";
    const columns = aspects ? 11 : 5;
    return `<details class="group catalog-group" open>
      <summary><span class="title">${esc(kind)}</span><span class="muted">${coverage.functional_or_better}/${coverage.total} functional+ · ${coverage.functional_or_better_percent}%</span></summary>
      <div class="catalog-distribution">${stackBar(coverage.by_status, coverage.total)}${legend(coverage.by_status)}</div>
      <div class="table-wrap"><table><thead><tr><th>Id</th><th>Name</th><th>Status</th>${aspectHeaders}<th>Evidence</th><th>Note</th></tr></thead><tbody>
      ${visible.map((row) => {
        const feature = row.feature ? data.features.find((item) => item.id === row.feature) : null;
        const aspectCells = aspects ? `${aspectNames.map((name) => `<td>${row.aspects ? aspectBadge(row.aspects[name]) : '<span class="muted">—</span>'}</td>`).join("")}<td>${row.aspects ? `<code>${esc(row.aspects.soul_ref)}</code>` : '<span class="muted">—</span>'}</td>` : "";
        return `<tr><td><code>${esc(typeof row.id === "number" ? "0x" + row.id.toString(16).toUpperCase().padStart(2, "0") : row.id)}</code></td><td>${esc(row.name)}${row.feature ? `<br><code class="muted">${esc(row.feature)}</code>` : ""}</td><td>${statusBadge(row.status)}</td>${aspectCells}<td>${evidenceBadges(row.evidence, feature && feature.verification)}</td><td class="muted">${esc(row.note || "")}</td></tr>`;
      }).join("") ||
      `<tr><td colspan="${columns}" class="muted">No match.</td></tr>`}
      </tbody></table></div></details>`;
  }

  /* The per-monster aspects (sprite, animations, sounds, loot, soul). */
  const aspectNames = ["sprite", "animations", "sounds", "loot", "soul"];

  function aspectBadge(value) {
    const kind = value === "ported" ? "ok" : value === "partial" ? "warn" : value === "missing" ? "bad" : "";
    return `<span class="badge ${kind}">${esc(value)}</span>`;
  }

  function aspectOverview(g) {
    const s = g.aspects;
    const totals = aspectNames.map((name) =>
      `<li><strong>${esc(name)}</strong> ${s[name].ported} ported · ${s[name].partial} partial · ${s[name].missing} missing</li>`).join("");
    return `<h3>Five-aspect monster completion <span class="muted">${s.complete}/${s.monsters} complete</span></h3>
      <p class="muted">${esc(g.aspects_note)} The aspect columns are included directly in the Monsters table below; monsters are not repeated in a second table.</p>
      <ul class="aspect-totals">${totals}</ul>`;
  }

  function bestiaryView() {
    const b = data.bestiary;
    if (!b || !b.games) return '<p class="notice">No bestiary data. Regenerate with <code>./build/fusion_dashboard</code>.</p>';
    const m = b.games.mzm, g = b.games.aos;
    if (!m || !m.coverage || !g || !g.coverage || !g.bosses || !g.souls)
      return '<p class="notice">The detailed game catalogs are missing. Regenerate the dashboard.</p>';
    return `<h2>Native monsters, bosses, items and souls</h2>
      <p class="notice">${esc(b.method)}</p>
      <section class="catalog-game catalog-mzm"><h2>${esc(m.title)}</h2>
        ${coverageCards([
          ["Enemy and boss actors", m.coverage.monsters, "mzm"],
          ["Items and pickups", m.coverage.items, "mzm"]
        ])}
        <p class="muted">${esc(m.items_note)}</p>
        ${bestiaryTable(m.monsters, "Enemy and boss actors", m.coverage.monsters, false)}
        ${bestiaryTable(m.items, "Items and pickups", m.coverage.items, false)}
      </section>
      <section class="catalog-game catalog-aos"><h2>${esc(g.title)}</h2>
        ${coverageCards([
          ["Monsters", g.coverage.monsters, "aos"], ["Bosses", g.coverage.bosses, "aos"],
          ["Items", g.coverage.items, "aos"], ["Red souls", g.coverage.red_souls, "aos"],
          ["Blue souls", g.coverage.blue_souls, "aos"],
          ["Yellow souls", g.coverage.yellow_souls, "aos"],
          ["Ability souls", g.coverage.ability_souls, "aos"]
        ])}
        ${aspectOverview(g)}
        ${bestiaryTable(g.monsters, "Monsters", g.coverage.monsters, true)}
        ${bestiaryTable(g.bosses, "Bosses", g.coverage.bosses, true)}
        <p class="muted">${esc(g.items_note)}</p>
        ${bestiaryTable(g.items, "Items", g.coverage.items, false)}
        ${bestiaryTable(g.souls.red, "Red souls (offensive)", g.coverage.red_souls, false)}
        ${bestiaryTable(g.souls.blue, "Blue souls (guardian)", g.coverage.blue_souls, false)}
        ${bestiaryTable(g.souls.yellow, "Yellow souls (passive)", g.coverage.yellow_souls, false)}
        ${bestiaryTable(g.souls.ability, "Ability souls (movement)", g.coverage.ability_souls, false)}
      </section>`;
  }

  function inGameView() {
    const allChecked = data.features.filter((f) => f.evidence && f.evidence.in_game_check.length);
    const checked = allChecked.filter(matches);
    const played = data.features.filter((f) => f.evidence && f.evidence.played_through);
    const compared = data.features.filter((f) => f.evidence && f.evidence.emulator_compared);
    return `<p class="notice">Recorded evidence across ${data.features.length} registered features:
      ${allChecked.length} checked manually in a runtime, ${compared.length} compared with an emulator,
      and ${played.length} played through. These counts are evidence, not completion percentages.</p>
      ${checked.length !== allChecked.length ? `<p class="filter-result">Showing ${checked.length} of ${allChecked.length} in-game checks after filters.</p>` : ""}
      ${featureGroups(checked, true)}`;
  }

  function render() {
    statusFilter.hidden = ["tests", "timeline"].includes(state.view);
    if (state.view === "overview") view.innerHTML = overview();
    else if (AREA_VIEWS.includes(state.view)) view.innerHTML = areaView(state.view);
    else if (state.view === "bestiary") view.innerHTML = bestiaryView();
    else if (state.view === "ingame") view.innerHTML = inGameView();
    else if (state.view === "tests") view.innerHTML = testsView();
    else if (state.view === "timeline") view.innerHTML = timelineView();
    else view.innerHTML = attentionView();
  }

  function init() {
    if (!data || data.schema !== "metroidvania-dashboard-v1") {
      view.innerHTML = '<p class="notice">No dashboard data. Generate it with <code>./build/fusion_dashboard --run-tests</code>.</p>';
      toolbar.hidden = true;
      return;
    }
    const when = new Date(data.generated_at);
    document.getElementById("generated").innerHTML =
      `Generated ${esc(when.toLocaleString())}<br><code>${esc(data.git.branch)}@${esc(data.git.commit)}</code>${data.git.dirty ? " (uncommitted changes)" : ""}`;
    statusFilter.innerHTML = data.statuses.map((s) =>
      `<button class="chip" data-status="${esc(s.id)}" aria-pressed="false" title="${esc(s.description)}"><span class="dot" style="background:var(--s-${esc(s.id)})"></span>${esc(s.label)}</button>`).join("");
    statusFilter.addEventListener("click", (event) => {
      const chip = event.target.closest(".chip");
      if (!chip) return;
      const id = chip.dataset.status;
      if (state.statuses.has(id)) state.statuses.delete(id); else state.statuses.add(id);
      chip.setAttribute("aria-pressed", String(state.statuses.has(id)));
      render();
    });
    search.addEventListener("input", () => { state.query = search.value.trim().toLowerCase(); render(); });
    view.addEventListener("click", (event) => {
      const link = event.target.closest("[data-open-view]");
      if (!link) return;
      const button = document.querySelector(`#tabs button[data-view="${link.dataset.openView}"]`);
      if (!button) return;
      event.preventDefault();
      button.click();
      window.scrollTo(0, 0);
    });
    document.getElementById("tabs").addEventListener("click", (event) => {
      const button = event.target.closest("button[data-view]");
      if (!button) return;
      document.querySelectorAll("#tabs button").forEach((b) => b.classList.toggle("active", b === button));
      state.view = button.dataset.view;
      try { history.replaceState(null, "", `#${state.view}`); } catch (e) { /* file:// may refuse */ }
      render();
    });
    document.querySelectorAll("[data-repo-path]").forEach((link) => {
      link.href = repositoryPath(link.dataset.repoPath);
    });
    const initial = (location.hash || "").slice(1);
    const button = [...document.querySelectorAll("#tabs button[data-view]")]
      .find((candidate) => candidate.dataset.view === initial);
    if (button) button.click(); else render();
  }

  init();
}());
